    { const char * tb_v873 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v873; }
    { const char * tb_v874 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v874; }
    { const char * tb_v875 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v875; }
    { const char * tb_v876 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v876; }
    { const char * tb_v877 = "TB_COLD static void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v877; }
    { const char * tb_v878 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v878; }
