    { const char * tb_v886 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v886; }
    { const char * tb_v887 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v887; }
    { const char * tb_v888 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v888; }
    { const char * tb_v889 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v889; }
    { const char * tb_v890 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v890; }
    { const char * tb_v891 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v891; }
    { const char * tb_v892 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v892; }
    { const char * tb_v893 = "static char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v893; }
