    { const char * tb_v897 = "    long long lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v897; }
    { const char * tb_v898 = "    struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v898; }
    { const char * tb_v899 = "    if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v899; }
    { const char * tb_v900 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v900; }
    { const char * tb_v901 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v901; }
    { const char * tb_v902 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v902; }
    { const char * tb_v903 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v903; }
    { const char * tb_v904 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v904; }
    { const char * tb_v905 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
    { const char * tb_v906 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v906; }
    { const char * tb_v907 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v907; }
    { const char * tb_v908 = "static void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v908; }
    { const char * tb_v909 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
    { const char * tb_v910 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v910; }
    { const char * tb_v911 = "    ss.ss_sp = alt; ss.ss_size = sizeof alt; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v911; }
    { const char * tb_v912 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
    { const char * tb_v914 = "    memset(&sa, 0, sizeof sa);\n"; *(const char * *)tb_grow(v_lines) = tb_v914; }
