    { const char * tb_v922 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v922; }
    { const char * tb_v923 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v923; }
    { const char * tb_v924 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v924; }
    { const char * tb_v925 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
    { const char * tb_v930 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v930; }
    { const char * tb_v931 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v931; }
    { const char * tb_v932 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v932; }
    { const char * tb_v933 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v933; }
    { const char * tb_v934 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v934; }
    { const char * tb_v935 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v935; }
    { const char * tb_v936 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
    { const char * tb_v940 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v940; }
    { const char * tb_v941 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v941; }
    { const char * tb_v942 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
    { const char * tb_v946 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v946; }
    { const char * tb_v947 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v947; }
    { const char * tb_v948 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v948; }
    { const char * tb_v949 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v949; }
    { const char * tb_v950 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v950; }
    { const char * tb_v951 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v951; }
