    { const char * tb_v955 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
    { const char * tb_v957 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v957; }
    { const char * tb_v958 = "static _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "static _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "static inline tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
