    { const char * tb_v969 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "static int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
