    { const char * tb_v997 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "static void *tb_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
